#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up a second runner for this repo's workflows inside WSL (Ubuntu) on the owner's Windows PC, beside the one on
# the Mac. Both carry the `aluminium` label, so a job runs on whichever is online. Run it in the Ubuntu terminal, as
# the user the runner will run as. gh, signed in as the owner, clones block (private) and gets the runner's
# registration token:
#   sudo apt-get update && sudo apt-get install -y gh && gh auth login
#   gh api repos/pawisssh/aluminium/contents/.github/runner-wsl.sh -H 'Accept: application/vnd.github.raw' > runner-wsl.sh
#   bash runner-wsl.sh
# Each stage skips what is already done, so a re-run picks up where the last one stopped.
REPO=pawisssh/aluminium
BLOCK=pawisssh/block
# check.yml's vendor:check reads block here, the same path as on the Mac.
BLOCK_DIR="$HOME/Projects/finnomena/block"
RUNNER_DIR="$HOME/actions-runner-aluminium"
CHECK_DIR="$HOME/aluminium-runner-check"
NODE_DIR="$HOME/.local/node-22"
DISTRO="${WSL_DISTRO_NAME:-Ubuntu}"
KEEPALIVE_TASK="WSL keep-alive ($DISTRO)"
RUNNER_NAME="$(hostname)-wsl-aluminium"
gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

run_wizard() {

TOTAL_STAGES=8

banner "An aluminium CI runner in WSL"

stage "Check WSL"
grep -qi microsoft /proc/version || { warn "This is not WSL: run the wizard in the Ubuntu terminal on the PC."; exit 1; }
[[ "$(uname -r)" == *WSL2* ]] || { warn "This is WSL 1. In PowerShell: wsl --set-version $DISTRO 2, then re-run."; exit 1; }
[[ "$(uname -m)" == x86_64 ]] || { warn "This wizard installs the x64 runner; this machine is $(uname -m)."; exit 1; }
gh_ready || { warn "Sign gh in as the repo's owner first (sudo apt-get install -y gh && gh auth login)."; exit 1; }
# Registering a runner needs admin on the repo; git (block's clone and its fetches) signs in through gh.
[[ "$(gh api "repos/$REPO" --jq .permissions.admin 2>/dev/null)" == true ]] ||
  { warn "gh's account ($(gh api user --jq .login 2>/dev/null || echo '?')) is not an admin of $REPO: gh auth login as its owner."; exit 1; }
gh auth setup-git
if [[ "$(ps -p 1 -o comm=)" != systemd ]]; then
  say "The runner runs as a systemd service, and systemd is off in this distro."
  if grep -qs '^\[boot\]' /etc/wsl.conf; then
    step "Add the line systemd=true under [boot] in /etc/wsl.conf:  sudo nano /etc/wsl.conf"
  elif confirm "Turn it on in /etc/wsl.conf (asks for your sudo password)?"; then
    printf '[boot]\nsystemd=true\n' | sudo tee -a /etc/wsl.conf >/dev/null
  else
    warn "The runner needs systemd; re-run once it is on."; exit 1
  fi
  step "In PowerShell, run:  wsl --shutdown"
  step "Open Ubuntu again and re-run this wizard."
  exit 0
fi
say "WSL 2, x86_64, systemd, gh signed in as an admin of $REPO: OK ($DISTRO)."
pause

stage "Keep WSL running"
say "WSL stops a distro soon after its last terminal closes, systemd services and all."
say "A Windows task started at logon keeps one process in it, so the runner stays up."
if schtasks.exe /Query /TN "$KEEPALIVE_TASK" >/dev/null 2>&1; then
  say "Task \"$KEEPALIVE_TASK\" is already there."
elif confirm "Create the Windows task \"$KEEPALIVE_TASK\"?"; then
  if schtasks.exe /Create /F /TN "$KEEPALIVE_TASK" /SC ONLOGON \
      /TR "powershell.exe -WindowStyle Hidden -Command wsl.exe -d $DISTRO --exec sleep infinity" >/dev/null &&
    schtasks.exe /Run /TN "$KEEPALIVE_TASK" >/dev/null; then
    say "Created and started."
  else
    warn "schtasks refused (a logon task may need an administrator). In an administrator PowerShell, run:"
    note "schtasks /Create /F /TN \"$KEEPALIVE_TASK\" /SC ONLOGON /TR \"powershell.exe -WindowStyle Hidden -Command wsl.exe -d $DISTRO --exec sleep infinity\""
    pause "Press Enter once it is created"
  fi
else
  warn "Without it the runner stops whenever no Ubuntu terminal is open."
fi
say "A sleeping PC takes no jobs either."
open_url "ms-settings:powersleep"
step "Screen and sleep → When plugged in, put my device to sleep after: Never."
pause

stage "Install git, jq, Node 22 and block"
say "apt packages, Node 22 from nodejs.org (checked against its SHASUMS256), and a clone of $BLOCK at"
say "$BLOCK_DIR. The workflows' jobs find jq and node on the runner's PATH."
sudo apt-get update -qq
sudo apt-get install -y -qq git jq curl ca-certificates xz-utils >/dev/null
if [[ ! -x "$NODE_DIR/bin/node" ]]; then
  tmp=$(mktemp -d)
  ( cd "$tmp"
    curl -fsSLO https://nodejs.org/dist/latest-v22.x/SHASUMS256.txt
    file=$(grep -oE 'node-v22\.[0-9.]+-linux-x64\.tar\.xz' SHASUMS256.txt | head -1)
    curl -fsSLO "https://nodejs.org/dist/latest-v22.x/$file"
    grep " $file\$" SHASUMS256.txt | sha256sum -c --quiet - || { warn "$file does not match SHASUMS256.txt."; exit 1; }
    mkdir -p "$NODE_DIR" && tar -xJf "$file" -C "$NODE_DIR" --strip-components=1 )
  rm -rf "${tmp:?}"
fi
export PATH="$NODE_DIR/bin:$PATH"
say "node $(node --version), $(jq --version)"
if [[ -d "$BLOCK_DIR/.git" ]]; then
  git -C "$BLOCK_DIR" fetch --quiet origin || { warn "Couldn't fetch $BLOCK in $BLOCK_DIR."; exit 1; }
  say "block is already at $BLOCK_DIR; fetched."
else
  mkdir -p "$(dirname "$BLOCK_DIR")"
  gh repo clone "$BLOCK" "$BLOCK_DIR" -- -q || { warn "Couldn't clone $BLOCK through gh."; exit 1; }
  say "Cloned $BLOCK to $BLOCK_DIR."
fi
pause

stage "Run the checks"
say "A fresh clone of $REPO's main, then check.yml's steps, as CI runs them."
say "The log goes to $CHECK_DIR.log."
rm -rf "${CHECK_DIR:?}"
gh repo clone "$REPO" "$CHECK_DIR" -- -q || { warn "Couldn't clone $REPO through gh."; exit 1; }
if ( set -e
     cd "$CHECK_DIR"
     for tool in tools/*/package.json; do
       ( cd "$(dirname "$tool")"
         npm ci --prefer-offline --no-audit --no-fund
         npm run check
         BLOCK_REPO="$BLOCK_DIR" npm run vendor:check --if-present )
     done
     jq -e . .claude/*.json >/dev/null
     for f in scripts/*.sh .githooks/*; do sh -n "$f"; done
     sh scripts/test-hooks.sh
     for f in scripts/*.mjs tools/*/scripts/*.mjs; do node --check "$f"; done ) >"$CHECK_DIR.log" 2>&1; then
  say "The checks passed."
else
  warn "A check failed. The last lines:"
  tail -n 20 "$CHECK_DIR.log" | sed 's/^/    /'
  say "Send $CHECK_DIR.log to Claude to fix, then re-run: a runner that fails here fails PRs."
  exit 1
fi
pause

stage "Download the runner"
if [[ -f "$RUNNER_DIR/config.sh" ]]; then
  say "Already in $RUNNER_DIR."
else
  release=$(curl -fsSL https://api.github.com/repos/actions/runner/releases/latest) ||
    { warn "Couldn't read the runner's latest release from api.github.com (rate limit?); re-run later."; exit 1; }
  version=$(printf '%s' "$release" | grep -oE '"tag_name": *"v[0-9.]+"' | grep -oE '[0-9][0-9.]+' || true)
  hash=$(printf '%s' "$release" | grep -oE 'BEGIN SHA linux-x64 -->[0-9a-f]{64}' | grep -oE '[0-9a-f]{64}' || true)
  [[ -n "$version" && -n "$hash" ]] || { warn "Couldn't read the runner's version and SHA-256 from its release notes."; exit 1; }
  file="actions-runner-linux-x64-$version.tar.gz"
  mkdir -p "$RUNNER_DIR"
  curl -fsSLo "$RUNNER_DIR/$file" "https://github.com/actions/runner/releases/download/v$version/$file"
  echo "$hash  $RUNNER_DIR/$file" | sha256sum -c --quiet - || { warn "$file does not match its release notes' SHA-256."; exit 1; }
  tar -xzf "$RUNNER_DIR/$file" -C "$RUNNER_DIR" && rm "${RUNNER_DIR:?}/${file:?}"
  sudo "$RUNNER_DIR/bin/installdependencies.sh" >/dev/null
  say "Runner $version, SHA-256 checked, in $RUNNER_DIR."
fi
pause

stage "Register the runner"
if [[ -f "$RUNNER_DIR/.runner" ]]; then
  say "Already registered."
else
  TOKEN=$(gh api -X POST "repos/$REPO/actions/runners/registration-token" --jq .token)
  ( cd "$RUNNER_DIR" && ./config.sh --unattended --replace --url "https://github.com/$REPO" --token "$TOKEN" \
      --name "$RUNNER_NAME" --labels aluminium )
fi
# The service's PATH is the runner's .path file. Jobs call node without setup-node, so Node's folder goes first.
if ! grep -qs "^$NODE_DIR/bin:" "$RUNNER_DIR/.path"; then
  runner_path="$NODE_DIR/bin:$(cat "$RUNNER_DIR/.path" 2>/dev/null || printf '%s' "$PATH")"
  printf '%s' "$runner_path" >"$RUNNER_DIR/.path"
fi
pause

stage "Start it as a service"
( cd "$RUNNER_DIR"
  [[ -f .service ]] || sudo ./svc.sh install "$USER"
  # A restart, so a service that was already running picks up .path.
  sudo ./svc.sh stop >/dev/null 2>&1 || true
  sudo ./svc.sh start >/dev/null
  sudo ./svc.sh status | grep -E 'Active:' | sed 's/^ */  /' || true )
pause

stage "Confirm GitHub sees it"
for _ in 1 2 3 4 5 6; do
  status=$(gh api "repos/$REPO/actions/runners" --jq ".runners[] | select(.name == \"$RUNNER_NAME\") | .status" || true)
  [[ "$status" == online ]] && break
  sleep 5
done
[[ "$status" == online ]] || { warn "GitHub lists $RUNNER_NAME as '${status:-missing}'. Check: sudo $RUNNER_DIR/svc.sh status"; exit 1; }
say "GitHub lists $RUNNER_NAME as online; it takes the next queued job."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
